  const vehiclePageMeta={vehicles:{title:'My Vehicles',description:'Manage your vehicles, odometer readings, and vehicle details.',action:<button className="btn btn-primary" onClick={openAddVehicle}><Plus size={16}/> Add vehicle</button>},maintenance:{title:'Maintenance',description:'Plan recurring maintenance by date, mileage, or both.',action:<button className="btn btn-primary" onClick={()=>{setPlanForm(f=>({...f,vehicle_id:f.vehicle_id||vehicles[0]?.id||''}));setPlanOpen(true)}} disabled={!vehicles.length}><Plus size={16}/> Add plan</button>},history:{title:'Service History',description:'Review repairs and completed services, and track their costs.',action:<button className="btn btn-primary" onClick={()=>{setServiceForm(f=>({...f,vehicle_id:f.vehicle_id||vehicles[0]?.id||''}));setServiceOpen(true)}} disabled={!vehicles.length}><Plus size={16}/> Log service</button>},fuel:{title:'Fuel Log',description:'Track fuel fill-ups, distance driven, and fuel spending for each vehicle.',action:<button className="btn btn-primary" onClick={()=>{setEditTarget(null);setFuelForm(f=>({...f,vehicle_id:f.vehicle_id||vehicles[0]?.id||'',account_id:f.account_id||accounts.find(a=>!isGoalsAccount(a))?.id||''}));setFuelOpen(true)}} disabled={!vehicles.length}><Plus size={16}/> Add fuel entry</button>}};
